(26717, 'Matthew 24:12', 'Matthew', 24, 12, 'بدکاري به دومره زیاته شي چې د خلکو مینه به یو د بله سره ورکه شي.', 'بدکاری به دومره زیاته شی چې د خلکو مینه به یو د بله سره ورکه شی.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Matthew_24_12.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237834, 1761237834),
(26718, 'Matthew 24:13', 'Matthew', 24, 13, 'خو څوک چې تر اخره پورې ټینګ پاتې شي هغه به خلاصون ومومي', 'خو چوک چې تر اخره پورې تینګ پاتې شی هغه به خلاصون ومومی', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Matthew_24_13.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237834, 1761237834),
(26719, 'Matthew 24:14', 'Matthew', 24, 14, 'او د اسماني پاچاهۍ زېری به په ټوله نړۍ کې خپور شي، ترڅو د ټولو قومونو دپاره شاهدي اوسي او بیا به نړۍ ختمه شي. د اخرې زمانې هیبتناکه وېره (مرقوس ۱۳‏:‌۱۴‌‏-‌۲۳ او لوقا ۲۱‏:‌۲۰‌‏-‌۲۴)', 'او د اسمانی پاچاهی زېری به په توله نری کې خپور شی، ترچو د تولو قومونو دپاره شاهدی اوسی او بیا به نری ختمه شی. د اخرې زمانې هیبتناکه وېره (مرقوس ۱۳‏:‌۱۴‌‏-‌۲۳ او لوقا ۲۱‏:‌۲۰‌‏-‌۲۴)', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Matthew_24_14.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237834, 1761237834),
(26720, 'Matthew 24:15', 'Matthew', 24, 15, 'نو کله چې تاسو هغه نجس شی چې د بربادۍ سبب ګرځي او سپېڅلی ځای ناپاکه کوي او دانیال نبي د هغو په هکله خبرې کړي دي، ووینئ. (لوستونکي دې پوه شي چې د دې معنی څه ده.)', 'نو کله چې تاسو هغه نجس شی چې د بربادی سبب ګرجی او سپېچلی جای ناپاکه کوی او دانیال نبی د هغو په هکله خبرې کری دی، ووینی. (لوستونکی دې پوه شی چې د دې معنی چه ده.)', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Matthew_24_15.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237834, 1761237834),
(26721, 'Matthew 24:16', 'Matthew', 24, 16, 'نو څوک چې په یهودیې کې وي هغه دې غرونو ته وتښتي.', 'نو چوک چې په یهودیې کې وی هغه دې غرونو ته وتشتی.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Matthew_24_16.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237834, 1761237834),
(26722, 'Matthew 24:17', 'Matthew', 24, 17, 'که څوک د بام په سر وي، نو هغه دې د کور د سامان د وړلو دپاره نه راښکته کیږي.', 'که چوک د بام په سر وی، نو هغه دې د کور د سامان د ورلو دپاره نه راشکته کیزی.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Matthew_24_17.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237834, 1761237834),
(26723, 'Matthew 24:18', 'Matthew', 24, 18, 'که څوک په پټي کې وي هغه دې د خپلې چپنې پسې بېرته کور ته نه ورځي.', 'که چوک په پتی کې وی هغه دې د خپلې چپنې پسې بېرته کور ته نه ورجی.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Matthew_24_18.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237834, 1761237834),
(26724, 'Matthew 24:19', 'Matthew', 24, 19, 'افسوس د هغو ښځو په حال چې په هغو ورځو کې امیدوارې وي او هغو میندو په حال چې خپلو ماشومانو ته شیدې ورکوي.', 'افسوس د هغو شجو په حال چې په هغو ورجو کې امیدوارې وی او هغو میندو په حال چې خپلو ماشومانو ته شیدې ورکوی.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Matthew_24_19.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237834, 1761237834),
(26725, 'Matthew 24:20', 'Matthew', 24, 20, 'دعا کوئ چې ستاسو تېښته په ژمي کې او یا د سبت په ورځ نه وي.', 'دعا کوی چې ستاسو تېشته په ژمی کې او یا د سبت په ورج نه وی.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Matthew_24_20.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237834, 1761237834),
(26726, 'Matthew 24:21', 'Matthew', 24, 21, 'ځکه چې په هغه وخت کې به داسې سخت مصیبت رامنځته شي چې د نړۍ له پیل څخه تر‌اوسه پورې نه دی راغلی او نه به بیا راشي.', 'جکه چې په هغه وخت کې به داسې سخت مصیبت رامنجته شی چې د نری له پیل چخه تر‌اوسه پورې نه دی راغلی او نه به بیا راشی.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Matthew_24_21.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237834, 1761237834),
(26727, 'Matthew 24:22', 'Matthew', 24, 22, 'که چېرې خدای هغه ورځې لنډې کړې نه وای نو هېڅوک به ژوندی پاتې شوی نه وای، خو خدای به د خپلو غوره شویو خلکو په خاطر هغه ورځې لنډې کړي.', 'که چېرې خدای هغه ورجې لندې کرې نه وای نو هېچوک به ژوندی پاتې شوی نه وای، خو خدای به د خپلو غوره شویو خلکو په خاطر هغه ورجې لندې کری.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Matthew_24_22.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237834, 1761237834),
(26728, 'Matthew 24:23', 'Matthew', 24, 23, 'که په هغه وخت کې څوک تاسو ته ووایي: ‹ګورئ، مسیح دلته دی یا هلته دی،› نو باور ورباندې مه کوئ.', 'که په هغه وخت کې چوک تاسو ته ووایی: ‹ګوری، مسیح دلته دی یا هلته دی،› نو باور ورباندې مه کوی.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Matthew_24_23.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237834, 1761237834),
